"""
Client for the qBraid Compute service.

"""

from typing import Any, NoReturn, Optional

from qbraid_core.client import QbraidClientV1
from qbraid_core.exceptions import RequestsApiError
from qbraid_core.registry import register_client

from .exceptions import (
    ComputeBuildError,
    ComputeInsufficientTierError,
    ComputePaymentRequiredError,
    ComputePermissionError,
    ComputeProfileNotFoundError,
    ComputeServiceRequestError,
)
from .schemas import (
    BMAInstance,
    BMAStatus,
    BuildStatusResponse,
    ComputeProfile,
    ComputeSession,
    ComputeUsage,
    ProfileCreateRequest,
    ProfileCreateResponse,
    ProfileDeleteResponse,
    ProfileDetails,
    ServerStartResponse,
    ServerStatus,
    ServerStopResponse,
    SessionTokenResponse,
)


@register_client()
class ComputeClient(QbraidClientV1):
    """Client for interacting with the qBraid Compute service.

    Manages compute profiles for try-mode and save-mode instances.

    Args:
        api_key: Optional API key for authentication.
        session: Optional pre-configured session.

    Example:
        >>> from qbraid_core.services.compute import ComputeClient
        >>> client = ComputeClient()
        >>> profiles = client.list_profiles()
        >>> for profile in profiles:
        ...     print(f"{profile.slug}: {profile.profile_type}")
    """

    def __init__(self, *args, **kwargs):
        """Initialize the ComputeClient."""
        super().__init__(*args, **kwargs)
        # Cache of docker-vm (BMA) profile slugs, populated lazily.
        self._bma_slugs: Optional[set[str]] = None

    def _handle_error(self, err: RequestsApiError, operation: str) -> NoReturn:
        """Handle API errors and raise appropriate exceptions."""
        err_str = str(err).lower()

        if "402" in err_str or "payment required" in err_str:
            # Extract the user-friendly message from the API response
            msg = str(err)
            raise ComputePaymentRequiredError(msg) from err

        if "404" in err_str or "not found" in err_str or "profile_not_found" in err_str:
            raise ComputeProfileNotFoundError(f"Profile not found: {err}") from err

        if "403" in err_str:
            if "insufficient_tier" in err_str:
                raise ComputeInsufficientTierError(
                    f"Plan below required tier for {operation}: {err}"
                ) from err
            if "cannot_delete_global" in err_str:
                raise ComputePermissionError("Cannot delete global profiles") from err
            raise ComputePermissionError(f"Permission denied for {operation}: {err}") from err

        if "400" in err_str and "not_save_mode" in err_str:
            raise ComputeBuildError("Build status only available for save-mode profiles") from err

        raise ComputeServiceRequestError(f"Failed to {operation}: {err}") from err

    # =========================================================================
    # Profile Listing
    # =========================================================================

    def list_profiles(
        self,
        plan: Optional[str] = None,
        gpu: Optional[bool] = None,
        visibility: Optional[str] = None,
        has_capacity: Optional[bool] = None,
        cluster_id: Optional[str] = None,
        page: Optional[int] = None,
        limit: Optional[int] = None,
        sort_by: Optional[str] = None,
        sort_order: Optional[str] = None,
    ) -> list[ComputeProfile]:
        """List available compute profiles.

        Args:
            plan: Filter by plan tier (e.g., "Free", "Standard", "Pro").
            gpu: Filter GPU profiles only.
            visibility: Filter by visibility ("public" or "private").
            has_capacity: Filter by capacity availability.
            cluster_id: Filter by cluster.
            page: Page number (min 1).
            limit: Results per page (1-100).
            sort_by: Sort field ("name", "rateDollar", "createdAt").
            sort_order: Sort direction ("asc" or "desc").

        Returns:
            List of ComputeProfile objects.

        Example:
            >>> profiles = client.list_profiles()
            >>> gpu_profiles = client.list_profiles(gpu=True, has_capacity=True)
        """
        params: dict[str, Any] = {}
        if plan is not None:
            params["plan"] = plan
        if gpu is not None:
            params["gpu"] = str(gpu).lower()
        if visibility is not None:
            params["visibility"] = visibility
        if has_capacity is not None:
            params["hasCapacity"] = str(has_capacity).lower()
        if cluster_id is not None:
            params["clusterId"] = cluster_id
        if page is not None:
            params["page"] = page
        if limit is not None:
            params["limit"] = limit
        if sort_by is not None:
            params["sortBy"] = sort_by
        if sort_order is not None:
            params["sortOrder"] = sort_order

        try:
            response = self.session.get("/compute/profiles", params=params if params else None)
            resp_json = response.json()
            profiles_data = resp_json.get("data", [])
            return [ComputeProfile.model_validate(p) for p in profiles_data]
        except RequestsApiError as err:
            self._handle_error(err, "list profiles")
        return None  # pragma: no cover

    def get_profile(self, slug: str) -> ProfileDetails:
        """Get detailed profile information by slug.

        Returns transformed profile with resource specs and pricing breakdown.

        Args:
            slug: The profile slug.

        Returns:
            ProfileDetails object with resources and pricing.

        Raises:
            ComputeProfileNotFoundError: If profile doesn't exist.
        """
        try:
            response = self.session.get(f"/compute/profiles/{slug}")
            resp_json = response.json()
            return ProfileDetails.model_validate(resp_json.get("data", resp_json))
        except RequestsApiError as err:
            self._handle_error(err, f"get profile '{slug}'")
        return None  # pragma: no cover

    # =========================================================================
    # Try-Mode Profiles (Standard+)
    # =========================================================================

    def create_try_profile(
        self,
        base_image: str,
        display_name: Optional[str] = None,
        description: Optional[str] = None,
        cpu_guarantee: Optional[float] = None,
        cpu_limit: Optional[float] = None,
        mem_guarantee: Optional[str] = None,
        mem_limit: Optional[str] = None,
        gpu: bool = False,
        ide: str = "lab",
        features: Optional[str] = None,
    ) -> ProfileCreateResponse:
        """Create a try-mode profile (Standard+ plan required).

        Try-mode profiles allow testing custom images without persistent storage.
        Rate limit: 10 per 15 minutes.

        Args:
            base_image: Base Docker image (required). E.g., "python:3.12-slim"
            display_name: Display name for the profile.
            description: Profile description.
            cpu_guarantee: Guaranteed CPU cores.
            cpu_limit: Maximum CPU cores.
            mem_guarantee: Guaranteed memory (e.g., "8G").
            mem_limit: Maximum memory.
            gpu: Whether to enable GPU.
            ide: IDE type ("lab" or "code").
            features: Comma-separated features (e.g., "claude,codeq").

        Returns:
            ProfileCreateResponse with slug and profile details.

        Raises:
            ComputeInsufficientTierError: If plan is below Standard.
            ComputeServiceRequestError: On API errors.

        Example:
            >>> response = client.create_try_profile(
            ...     base_image="python:3.12-slim",
            ...     display_name="My Python Env",
            ...     cpu_guarantee=2.0,
            ...     mem_guarantee="4G"
            ... )
            >>> print(response.slug)
            'python-3-12-slim-try-bd332987'
        """
        request = ProfileCreateRequest(
            base_image=base_image,
            display_name=display_name,
            description=description,
            cpu_guarantee=cpu_guarantee,
            cpu_limit=cpu_limit,
            mem_guarantee=mem_guarantee,
            mem_limit=mem_limit,
            gpu=gpu,
            ide=ide,
            features=features,
        )

        try:
            response = self.session.post(
                "/compute/profiles/try",
                json=request.model_dump(by_alias=True, exclude_none=True),
            )
            resp_json = response.json()
            return ProfileCreateResponse.model_validate(resp_json.get("data", resp_json))
        except RequestsApiError as err:
            self._handle_error(err, "create try-mode profile")
        return None  # pragma: no cover

    # =========================================================================
    # Save-Mode Profiles (Pro+)
    # =========================================================================

    def create_save_profile(
        self,
        base_image: str,
        display_name: Optional[str] = None,
        description: Optional[str] = None,
        cpu_guarantee: Optional[float] = None,
        cpu_limit: Optional[float] = None,
        mem_guarantee: Optional[str] = None,
        mem_limit: Optional[str] = None,
        gpu: bool = False,
        ide: str = "lab",
        features: Optional[str] = None,
    ) -> ProfileCreateResponse:
        """Create a save-mode profile (Pro+ plan required).

        Save-mode profiles build a custom overlay image with persistent storage.
        The build is asynchronous - use get_build_status() to check progress.
        Rate limit: 5 per 15 minutes.

        Args:
            base_image: Base Docker image (required). E.g., "python:3.12-slim"
            display_name: Display name for the profile.
            description: Profile description.
            cpu_guarantee: Guaranteed CPU cores.
            cpu_limit: Maximum CPU cores.
            mem_guarantee: Guaranteed memory (e.g., "8G").
            mem_limit: Maximum memory.
            gpu: Whether to enable GPU.
            ide: IDE type ("lab" or "code").
            features: Comma-separated features (e.g., "claude,codeq").

        Returns:
            ProfileCreateResponse with slug, build_info, and has_capacity.

        Raises:
            ComputeInsufficientTierError: If plan is below Pro.
            ComputeServiceRequestError: On API errors.

        Example:
            >>> response = client.create_save_profile(
            ...     base_image="python:3.12-slim",
            ...     display_name="ML Environment",
            ...     mem_guarantee="16G",
            ...     gpu=True
            ... )
            >>> print(response.build_info.status)
            'QUEUED'
        """
        request = ProfileCreateRequest(
            base_image=base_image,
            display_name=display_name,
            description=description,
            cpu_guarantee=cpu_guarantee,
            cpu_limit=cpu_limit,
            mem_guarantee=mem_guarantee,
            mem_limit=mem_limit,
            gpu=gpu,
            ide=ide,
            features=features,
        )

        try:
            response = self.session.post(
                "/compute/profiles/save",
                json=request.model_dump(by_alias=True, exclude_none=True),
            )
            resp_json = response.json()
            return ProfileCreateResponse.model_validate(resp_json.get("data", resp_json))
        except RequestsApiError as err:
            self._handle_error(err, "create save-mode profile")
        return None  # pragma: no cover

    # =========================================================================
    # Build Status
    # =========================================================================

    def get_build_status(self, slug: str) -> BuildStatusResponse:
        """Check build status for a save-mode profile.

        Args:
            slug: The profile slug.

        Returns:
            BuildStatusResponse with current build status.

        Raises:
            ComputeProfileNotFoundError: If profile doesn't exist.
            ComputeBuildError: If profile is not save-mode.

        Example:
            >>> status = client.get_build_status("python-3-12-slim-saved-bd332987")
            >>> if status.build_info.status == BuildStatus.SUCCESS:
            ...     print("Build complete!")
        """
        try:
            response = self.session.get(f"/compute/profiles/{slug}/build-status")
            resp_json = response.json()
            return BuildStatusResponse.model_validate(resp_json.get("data", resp_json))
        except RequestsApiError as err:
            self._handle_error(err, f"get build status for '{slug}'")
        return None  # pragma: no cover

    def wait_for_build(
        self,
        slug: str,
        poll_interval: float = 5.0,
        timeout: Optional[float] = None,
    ) -> BuildStatusResponse:
        """Wait for a save-mode profile build to complete.

        Args:
            slug: The profile slug.
            poll_interval: Seconds between status checks (default: 5).
            timeout: Maximum seconds to wait (default: None = no timeout).

        Returns:
            BuildStatusResponse with final build status.

        Raises:
            ComputeBuildError: If build fails, times out, or is cancelled.
            TimeoutError: If timeout is reached.

        Example:
            >>> response = client.create_save_profile(base_image="python:3.12-slim")
            >>> final_status = client.wait_for_build(response.slug, timeout=300)
        """
        import time

        from .schemas import BuildStatus

        start_time = time.time()
        terminal_statuses = {
            BuildStatus.SUCCESS,
            BuildStatus.FAILURE,
            BuildStatus.TIMEOUT,
            BuildStatus.CANCELLED,
        }

        while True:
            status = self.get_build_status(slug)

            if status.build_info.status in terminal_statuses:
                if status.build_info.status != BuildStatus.SUCCESS:
                    raise ComputeBuildError(
                        f"Build failed with status: {status.build_info.status.value}"
                    )
                return status

            if timeout is not None:
                elapsed = time.time() - start_time
                if elapsed >= timeout:
                    raise TimeoutError(
                        f"Build did not complete within {timeout} seconds. "
                        f"Current status: {status.build_info.status.value}"
                    )

            time.sleep(poll_interval)

    # =========================================================================
    # Profile Deletion
    # =========================================================================

    def delete_profile(self, slug: str) -> ProfileDeleteResponse:
        """Delete a user-owned profile.

        Only user-owned profiles (try/save mode) can be deleted.
        Global profiles cannot be deleted.

        Args:
            slug: The profile slug to delete.

        Returns:
            ProfileDeleteResponse confirming deletion.

        Raises:
            ComputeProfileNotFoundError: If profile doesn't exist.
            ComputePermissionError: If not owner or trying to delete global profile.

        Example:
            >>> result = client.delete_profile("python-3-12-slim-try-bd332987")
            >>> print(result.deleted)
            True
        """
        try:
            response = self.session.delete(f"/compute/profiles/{slug}")
            resp_json = response.json()
            return ProfileDeleteResponse.model_validate(resp_json.get("data", resp_json))
        except RequestsApiError as err:
            self._handle_error(err, f"delete profile '{slug}'")
        return None  # pragma: no cover

    # =========================================================================
    # Convenience Methods
    # =========================================================================

    def list_my_profiles(self) -> list[ComputeProfile]:
        """List only user-owned profiles (excludes global profiles).

        Returns:
            List of user-owned ComputeProfile objects.
        """
        profiles = self.list_profiles()
        return [p for p in profiles if p.is_owner]

    def list_ready_profiles(self) -> list[ComputeProfile]:
        """List profiles that are ready to use (have capacity).

        Returns:
            List of ComputeProfile objects with has_capacity=True.
        """
        profiles = self.list_profiles()
        return [p for p in profiles if p.has_capacity]

    # =========================================================================
    # SSH Configuration
    # =========================================================================

    def configure_ssh(
        self,
        slug: str,
        ssh_host: str = "ssh.lab.qbraid.com",
        username: str = "jovyan",
        tools: Optional[list[str]] = None,
    ) -> dict:
        """Configure SSH access for a profile.

        Sets up SSH config entries and configures remote development tools
        for accessing the pod associated with this profile.

        Args:
            slug: Profile slug to configure SSH for.
            ssh_host: SSH host (default: ssh.lab.qbraid.com).
            username: SSH username (default: jovyan).
            tools: List of tools to configure. Options: "vscode", "cursor",
                   "claude-code", "codex". Default: all tools.

        Returns:
            Dict with configuration details for each tool.

        Example:
            >>> config = client.configure_ssh(
            ...     "python-3-12-slim-try-bd332987",
            ...     tools=["vscode", "cursor"]
            ... )
            >>> print(config["vscode"]["command"])
            'code --remote ssh-remote+qbraid-python-3-12-slim-try-bd332987 /home/jovyan'
        """
        from .ssh import PodConnection, RemoteTool, configure_remote_tool

        connection = PodConnection(
            slug=slug,
            username=username,
            ssh_host=ssh_host,
        )

        if tools is None:
            tools = ["vscode", "cursor", "claude-code", "codex"]

        result = {}
        for tool_name in tools:
            try:
                tool = RemoteTool(tool_name)
                result[tool_name] = configure_remote_tool(tool, connection)
            except ValueError:
                result[tool_name] = {"error": f"Unknown tool: {tool_name}"}

        return result

    def get_ssh_command(
        self,
        slug: str,
        ssh_host: str = "ssh.lab.qbraid.com",
        username: str = "jovyan",
    ) -> str:
        """Get SSH command for connecting to a profile's pod.

        Args:
            slug: Profile slug.
            ssh_host: SSH host.
            username: SSH username.

        Returns:
            SSH command string.

        Example:
            >>> cmd = client.get_ssh_command("my-profile")
            >>> print(cmd)
            'ssh jovyan@ssh.lab.qbraid.com -p 22'
        """
        from .ssh import PodConnection, get_ssh_command

        connection = PodConnection(
            slug=slug,
            username=username,
            ssh_host=ssh_host,
        )
        return get_ssh_command(connection)

    def remove_ssh_config(self, slug: str) -> bool:
        """Remove SSH configuration for a profile.

        Args:
            slug: Profile slug.

        Returns:
            True if config was removed, False if not found.
        """
        from .ssh import remove_pod_ssh_config

        return remove_pod_ssh_config(slug)

